#include <stdio.h>
#include <stdlib.h>
#include <string.h>
int mn(int a, int b)  {
    return a < b ? a : b;
}
int mx(int a, int b)  {
    return a > b ? a : b;
}
int read(void)  {
    int x = 0;
    if (scanf("%d", &x) != 1) return 0;
    return x;
}
int readstr(int* a)  {
    char s[20001];
    if (scanf("%20000s", s) != 1) return 0;
    if (strcmp(s, "-") == 0) return 0;
    int n = (int)strlen(s);
    for (int i = 0; i < n; i++) a[i] = (unsigned char)s[i];
    return n;
}
void emit(int x)  {
    printf("%d ", x);
}
void emitstr(int* a, int n)  {
    if (n == 0) putchar('-');
    for (int i = 0; i < n; i++) putchar(a[i]);
    putchar(' ');
}
int main(void)  {
    static int a[20000];
    static int b[20000];
    static int d[20000];
    static int e[20000];
    int l = 0, m = 0, r = 0, x = 0;
    // x 的上限是 10^8，因此答案最多 10000，10001 可作不可行上界。
    x = read();
    l = 0;
    r = 10001;
    // l 的平方不超 x，r 的平方超 x；两边之间还有整数时才继续。
    while ((l + 1) < r)  {
        m = ((l + r) / 2);
        if ((m * m) <= x)  {
            l = m;
        }
        else  {
            r = m;
        }
    }
    // 相邻边界之间没有别的整数，l 就是最大的可行平方根。
    emit(l);
    return 0;
}

